files.content:
// <file-drive> — a file browser whose index IS a query over the workbook's store.
//
// The files reinvention: a file is not a separate filesystem object, it's a ROW
// in the workbook's SQLite — a content-addressed record (name, path/key, type,
// size, modified, content-hash). So a "drive" is just a view over a query, the
// same way <grid-table> is a grid over a query and <record-list> is a card
// index. It reuses the SAME shared engine (getEngine) — never a second store —
// but renders a file/icon browser surface (grid of typed tiles or a detail
// list), NOT a tabular grid. Sorting/filtering push to SQL in the engine.
//
// Selecting a file emits `work-file-select` carrying the file's columns as a flat
// object; wire it to a <file-card>'s attributes to drive an inline preview.
//
// Usage (named source, drive a preview):
//   <file-drive src-name="assets"
//     query="SELECT name, path, type, size, modified, hash FROM assets"
//     name-field="name" path-field="path" type-field="type"
//     size-field="size" modified-field="modified" hash-field="hash"
//     view="grid" sort="modified" dir="desc" searchable></file-drive>
//
// Attributes:
//   src-name        a source registered via getEngine().register(...)
//   query           full SQL over the source (default SELECT * over src-name)
//   name-field      column shown as the file name        (default "name")
//   path-field      column with the path / content key   (default "path")
//   type-field      column with the mime/type or ext     (default "type")
//   size-field      column with the byte size            (default "size")
//   modified-field  column with the modified timestamp   (default "modified")
//   hash-field      column with the content-hash         (default "hash")
//   sort            initial sort column (one of the fields above)
//   dir             initial sort direction asc | desc    (default "asc")
//   searchable      show a filter box (filters IN the engine via WHERE … LIKE)
//   selected        the path/key of the currently active file (reflected)
//   view            grid | list                          (variant)
//   variant         framed | bare                        (visual shell)
//
// Events:
//   work-drive-ready  { detail: { rowCount, columns, types, engine } }
//   work-file-select  { detail: { file, index } }   file = flat {col:value}
import { WbElement, html, css, define } from "../../core/element.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";
import { getEngine } from "../../data/index.js";
import { fileKind, kindGlyph, fmtBytes, fmtWhen, extOf } from "./file-types.js";

const VARIANTS = defineVariants({
  view: { options: ["grid", "list"], default: "grid" },
  variant: { options: ["framed", "bare"], default: "framed" },
});

export class WbDrive extends WbElement {
  static variants = VARIANTS;
  static props = [
    ...variantAttrs(VARIANTS),
    "src-name", "query", "name-field", "path-field", "type-field",
    "size-field", "modified-field", "hash-field", "sort", "dir",
    "searchable", "selected",
  ];

  // The element reads its state via this.attr() in render() and drives its own
  // repaints (requestUpdate / _load) from attributeChangedCallback — so it must
  // observe every prop attribute itself.
  static get observedAttributes() { return this.props; }

  static styles = css`
    :host { display: block; font-family: var(--work-font); color: var(--work-fg); }
    .shell { border: 1px solid var(--work-border); border-radius: var(--work-radius);
      background: var(--work-surface); overflow: hidden; box-shadow: var(--work-shadow-sm); }
    :host([variant="bare"]) .shell { border: none; box-shadow: none; background: transparent; }

    .toolbar { display: flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-2) var(--work-space-3); border-bottom: 1px solid var(--work-border);
      background: var(--work-surface-soft); }
    .grow { flex: 1; }
    .search { font: inherit; font-size: var(--work-text-sm); color: var(--work-fg);
      background: var(--work-surface); border: 1px solid var(--work-border); border-radius: var(--work-radius-sm);
      padding: var(--work-space-1) var(--work-space-2); min-width: 150px; }
    .search:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--work-ring); border-color: var(--work-brand); }
    .sort { font: inherit; font-size: var(--work-text-sm); color: var(--work-fg);
      background: var(--work-surface); border: 1px solid var(--work-border); border-radius: var(--work-radius-sm);
      padding: var(--work-space-1) var(--work-space-2); cursor: pointer; }
    .vbtn { display: inline-flex; gap: var(--work-space-px); border: 1px solid var(--work-border); border-radius: var(--work-radius-sm); overflow: hidden; }
    .vbtn button { appearance: none; cursor: pointer; border: none; background: var(--work-surface);
      color: var(--work-fg-muted); font: 600 var(--work-text-sm)/1 var(--work-font); padding: var(--work-space-1) var(--work-space-2); }
    .vbtn button[aria-pressed="true"] { background: var(--work-brand-soft); color: var(--work-brand); }
    .meta { font-family: var(--work-font-mono); font-size: var(--work-text-sm); color: var(--work-fg-muted); }

    /* grid of file tiles */
    .grid { max-height: var(--work-drive-max-h, 460px); overflow: auto;
      padding: var(--work-space-3); display: grid; gap: var(--work-space-3);
      grid-template-columns: repeat(auto-fill, minmax(132px, 1fr)); }

    .tile { text-align: center; cursor: pointer; font: inherit; color: var(--work-fg);
      border: 1px solid var(--work-border); border-radius: var(--work-radius);
      background: var(--work-surface); padding: var(--work-space-3) var(--work-space-2);
      display: flex; flex-direction: column; align-items: center; gap: var(--work-space-2);
      transition: border-color var(--work-dur) var(--work-ease), box-shadow var(--work-dur) var(--work-ease), transform var(--work-dur) var(--work-ease); }
    .tile:hover { border-color: var(--work-border-strong); transform: translateY(-1px); box-shadow: var(--work-shadow-sm); }
    .tile[aria-selected="true"] { border-color: var(--work-brand); box-shadow: 0 0 0 1px var(--work-brand), var(--work-shadow-sm); background: var(--work-brand-soft); }
    .tile:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--work-ring); }

    .icon { width: 48px; height: 48px; display: grid; place-items: center;
      border-radius: var(--work-radius-sm); font-size: var(--work-text-metric-sm); line-height: 1;
      background: var(--work-surface-soft); color: var(--work-fg-muted); }
    .icon[data-kind="image"]  { background: var(--work-chip-lavender); color: var(--work-brand-ink); }
    .icon[data-kind="video"]  { background: var(--work-chip-peach);    color: var(--work-brand-ink); }
    .icon[data-kind="audio"]  { background: var(--work-chip-green);    color: var(--work-brand-ink); }
    .icon[data-kind="text"]   { background: var(--work-chip-blue);     color: var(--work-brand-ink); }
    .ext { font-family: var(--work-font-mono); font-size: var(--work-text-3xs); letter-spacing: .04em;
      text-transform: uppercase; opacity: .8; margin-top: 2px; }
    .name { font-size: var(--work-text-sm); font-weight: 600; max-width: 100%;
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .sub { font-family: var(--work-font-mono); font-size: var(--work-text-2xs); color: var(--work-fg-subtle); }

    /* list / detail rows */
    .rows { max-height: var(--work-drive-max-h, 460px); overflow: auto; }
    .head, .row { display: grid;
      grid-template-columns: 1.6fr .7fr .7fr 1fr; align-items: center;
      gap: var(--work-space-3); padding: var(--work-space-2) var(--work-space-3); }
    .head { position: sticky; top: 0; background: var(--work-surface-soft);
      border-bottom: 1px solid var(--work-border); font-family: var(--work-font-mono);
      font-size: var(--work-text-2xs); text-transform: uppercase; letter-spacing: .05em; color: var(--work-fg-subtle); }
    .row { cursor: pointer; border-bottom: 1px solid var(--work-border);
      transition: background var(--work-dur) var(--work-ease); }
    .row:hover { background: var(--work-surface-soft); }
    .row[aria-selected="true"] { background: var(--work-brand-soft); }
    .row:focus-visible { outline: none; box-shadow: inset 0 0 0 2px var(--work-ring); }
    .cell-name { display: flex; align-items: center; gap: var(--work-space-2); min-width: 0; }
    .ricon { width: 26px; height: 26px; flex: none; display: grid; place-items: center;
      border-radius: var(--work-radius-sm); font-size: var(--work-text); background: var(--work-surface-soft); color: var(--work-fg-muted); }
    .ricon[data-kind="image"]  { background: var(--work-chip-lavender); color: var(--work-brand-ink); }
    .ricon[data-kind="video"]  { background: var(--work-chip-peach);    color: var(--work-brand-ink); }
    .ricon[data-kind="audio"]  { background: var(--work-chip-green);    color: var(--work-brand-ink); }
    .ricon[data-kind="text"]   { background: var(--work-chip-blue);     color: var(--work-brand-ink); }
    .rname { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .num { font-family: var(--work-font-mono); font-size: var(--work-text-sm); color: var(--work-fg-muted); }

    .foot { display: flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-2) var(--work-space-3); border-top: 1px solid var(--work-border);
      font-size: var(--work-text-sm); color: var(--work-fg-subtle); }
    .engine { display: inline-flex; align-items: center; gap: var(--work-space-1); }
    .dot { width: 7px; height: 7px; border-radius: var(--work-radius-pill); background: var(--work-brand);
      box-shadow: 0 0 0 3px var(--work-brand-soft); }
    .engine[data-tier="memory"] .dot { background: var(--work-warn); box-shadow: 0 0 0 var(--work-space-3px) var(--work-warn-glow); }
    .engine[data-tier="error"] .dot { background: var(--work-err); box-shadow: none; }
    .empty { padding: var(--work-space-5); text-align: center; color: var(--work-fg-muted); font-size: var(--work-text-sm); }
  `;

  connectedCallback() {
    if (this._init == null) {
      this._init = true;
      this._engine = getEngine();
      this._result = null;
      this._filter = "";
      this._tier = "memory";
      this._error = null;
      this._busy = true;
    }
    super.connectedCallback();
    this._load();
    this._connected = true;
  }

  attributeChangedCallback(name, old, val) {
    // Reads state via this.attr() in render() and drives its own repaints — does
    // NOT delegate to Lit's attributeChangedCallback (unused property machinery).
    if (!this._connected) return;
    if (name === "src-name" || name === "query" || name === "sort" || name === "dir") this._load();
    else this.requestUpdate(); // view (grid/list markup), selected (aria), variant → repaint
  }

  // ── field resolution ────────────────────────────────────────────────────────
  _f(attr, dflt) {
    const v = this.attr(attr);
    if (v && this._has(v)) return v;
    if (this._has(dflt)) return dflt;
    return null;
  }
  _has(col) { return !!this._result && this._result.columns.includes(col); }
  _nameCol() { return this._f("name-field", "name") || (this._result?.columns[0]); }
  _pathCol() { return this._f("path-field", "path") || this._nameCol(); }
  _typeCol() { return this._f("type-field", "type"); }
  _sizeCol() { return this._f("size-field", "size"); }
  _modCol()  { return this._f("modified-field", "modified"); }
  _hashCol() { return this._f("hash-field", "hash"); }

  async _load() {
    if (this._loading) { this._loadAgain = true; return; }
    this._loading = true;
    do {
      this._loadAgain = false;
      this._busy = true; this._error = null; this.requestUpdate();
      try {
        const sname = this.attr("src-name");
        if (sname) await this._engine.whenRegistered(sname);
        await this._run();
      } catch (e) {
        this._error = String((e && e.message) || e);
        this._tier = "error";
      }
      this._busy = false;
      this.requestUpdate();
      this._emit("work-drive-ready", {
        rowCount: this._result?.rowCount || 0,
        columns: this._result?.columns || [],
        types: this._result?.types || [],
        engine: this._tier,
      });
    } while (this._loadAgain);
    this._loading = false;
  }

  async _run() {
    this._result = await this._engine.query(this._buildSql());
    this._tier = this._result.engine || this._engine.provider();
  }

  _buildSql() {
    const base = this.attr("query");
    const name = this.attr("src-name");
    const from = base ? `(${base.replace(/;$/, "")}) AS _q` : ident(name || "");
    let sql = `SELECT * FROM ${from}`;
    if (this._filter) {
      const f = this._filter.replace(/'/g, "''");
      // filter on the name + path + type fields (whatever exist on the result)
      const cols = [this.attr("name-field") || "name", this.attr("path-field") || "path", this.attr("type-field") || "type"]
        .filter((c, i, a) => c && a.indexOf(c) === i);
      const ors = cols.map((c) => `CAST(${ident(c)} AS VARCHAR) LIKE '%${f}%'`);
      if (ors.length) sql = `SELECT * FROM (${sql}) AS _s WHERE ${ors.join(" OR ")}`;
    }
    const sort = this.attr("sort");
    if (sort) {
      const dir = (this.attr("dir") || "asc").toLowerCase() === "desc" ? "DESC" : "ASC";
      sql = `SELECT * FROM (${sql}) AS _o ORDER BY ${ident(sort)} ${dir}`;
    }
    return sql;
  }

  // ── render ──────────────────────────────────────────────────────────────────
  render() {
    const searchable = this.boolAttr("searchable");
    const tierText = this._busy ? "querying…" : this._error ? "engine error" :
      this._tier === "runtime" ? "engine: runtime SQLite (VFS)" :
      this._tier === "sqlite-wasm" ? "engine: sqlite-wasm (in-page)" :
      "engine: in-JS (offline)";
    return html`<div class="shell">
      <div class="toolbar">
        ${searchable ? html`<input class="search" type="search" placeholder="Filter files…"
          aria-label="Filter files" .value=${this._filter} @input=${this._onSearch} />` : null}
        ${this._renderSort()}
        <span class="grow"></span>
        <div class="vbtn" role="group" aria-label="view">
          <button class="vg" aria-pressed=${String(this.attr("view") !== "list")}
            title="Grid view" @click=${() => this.setAttribute("view", "grid")}>▦</button>
          <button class="vl" aria-pressed=${String(this.attr("view") === "list")}
            title="List view" @click=${() => this.setAttribute("view", "list")}>☰</button>
        </div>
        <span class="meta">${this._result ? this._result.rowCount.toLocaleString() + " files" : ""}</span>
      </div>
      ${this._renderBody()}
      <div class="foot">
        <span class="engine" data-tier=${this._error ? "error" : this._tier}><span class="dot"></span></span>
        <span>${tierText}</span><span class="grow"></span>
        <span class="meta">content-addressed index · files = rows</span>
      </div></div>`;
  }

  _renderSort() {
    const opts = [
      ["", "Sort…"], ["name", "Name"], ["type", "Type"],
      ["size", "Size"], ["modified", "Modified"],
    ].filter(([v]) => !v || this._fieldFor(v));
    const cur = this.attr("sort") || "";
    return html`<select class="sort" title="Sort by" aria-label="Sort by" @change=${this._onSort}>
      ${opts.map(([v, l]) => html`<option value=${v} ?selected=${v === cur}>${l}</option>`)}
    </select>`;
  }
  _onSort(e) {
    const v = e.target.value;
    if (v) { this.setAttribute("sort", v); } else { this.removeAttribute("sort"); this._load(); }
  }
  // map a logical sort key to the configured column (default = same name)
  _fieldFor(key) {
    const map = { name: this.attr("name-field") || "name", type: this.attr("type-field") || "type",
      size: this.attr("size-field") || "size", modified: this.attr("modified-field") || "modified" };
    const col = map[key];
    return this._has(col) ? col : null;
  }

  _renderBody() {
    if (this._busy && !this._result) return html`<div class="empty">Loading…</div>`;
    if (this._error) return html`<div class="empty">Could not load — ${this._error}</div>`;
    const r = this._result;
    if (!r || !r.rows.length) return html`<div class="empty">${this._filter ? "No matching files." : "No files."}</div>`;
    return this.attr("view") === "list" ? this._renderList() : this._renderGrid();
  }

  _files() {
    const r = this._result;
    const idx = (c) => (c == null ? -1 : r.columns.indexOf(c));
    const nC = idx(this._nameCol()), pC = idx(this._pathCol()), tC = idx(this._typeCol());
    const sC = idx(this._sizeCol()), mC = idx(this._modCol()), hC = idx(this._hashCol());
    return r.rows.map((row, i) => {
      const file = {};
      r.columns.forEach((c, j) => (file[c] = row[j]));
      const name = nC >= 0 ? row[nC] : (pC >= 0 ? row[pC] : "");
      const path = pC >= 0 ? row[pC] : name;
      const type = tC >= 0 ? row[tC] : "";
      return {
        i, file, name: name ?? "", path: path ?? "", type: type ?? "",
        size: sC >= 0 ? row[sC] : null, modified: mC >= 0 ? row[mC] : null,
        hash: hC >= 0 ? row[hC] : null, kind: fileKind(type, name),
      };
    });
  }

  _renderGrid() {
    const selected = this.attr("selected");
    const tiles = this._files().map((f) => {
      const sel = selected != null && String(f.path) === String(selected);
      const ext = extOf(f.name) || extOf(f.type);
      return html`<button class="tile" role="option" aria-selected=${String(sel)}
        data-i=${f.i} data-path=${f.path}
        @click=${() => this._select(f.i)} @keydown=${(e) => this._onKey(e, f.i)}>
        <span class="icon" data-kind=${f.kind}>${kindGlyph(f.kind)}${ext ? html`<span class="ext">${ext}</span>` : null}</span>
        <span class="name" title=${f.name}>${f.name || "—"}</span>
        <span class="sub">${f.size != null ? fmtBytes(f.size) : f.kind}</span>
      </button>`;
    });
    return html`<div class="grid" role="listbox">${tiles}</div>`;
  }

  _renderList() {
    const selected = this.attr("selected");
    const rows = this._files().map((f) => {
      const sel = selected != null && String(f.path) === String(selected);
      return html`<div class="row" role="option" tabindex="0" aria-selected=${String(sel)}
        data-i=${f.i} data-path=${f.path}
        @click=${() => this._select(f.i)} @keydown=${(e) => this._onKey(e, f.i)}>
        <span class="cell-name">
          <span class="ricon" data-kind=${f.kind}>${kindGlyph(f.kind)}</span>
          <span class="rname" title=${f.name}>${f.name || "—"}</span>
        </span>
        <span class="num">${f.type || f.kind}</span>
        <span class="num">${f.size != null ? fmtBytes(f.size) : "—"}</span>
        <span class="num">${f.modified != null ? fmtWhen(f.modified) : "—"}</span>
      </div>`;
    });
    return html`<div class="rows" role="listbox">
      <div class="head"><span>Name</span><span>Type</span><span>Size</span><span>Modified</span></div>
      ${rows}</div>`;
  }

  // ── interaction ─────────────────────────────────────────────────────────────
  // Debounced search: filters IN the engine, then re-renders. Lit's surgical
  // update keeps the live <input> (and its focus/caret) intact across re-renders.
  _onSearch(e) {
    const value = e.target.value;
    clearTimeout(this._t);
    this._t = setTimeout(() => { this._filter = value; this._run().then(() => this.requestUpdate()); }, 140);
  }

  _onKey(e, i) {
    if (e.key === "Enter" || e.key === " ") { e.preventDefault(); this._select(i); }
  }

  _select(i) {
    const f = this._files().find((x) => x.i === i);
    if (!f) return;
    this.setAttribute("selected", f.path == null ? "" : String(f.path));
    this._emit("work-file-select", { file: f.file, index: i });
  }

  _emit(name, detail) {
    this.dispatchEvent(new CustomEvent(name, { detail, bubbles: true, composed: true }));
  }
}

function ident(name) { return '"' + String(name).replace(/"/g, '""') + '"'; }

define("file-drive", WbDrive);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}

// workponents · data — THE shared query/result contract.
//
// This is the single data interface every data surface consumes:
// `tables`, `data-viz`, `maps`, `records`, and `search` all talk to ONE engine
// through this shape. It is framework-agnostic, zero-dependency, and TOKEN-UNAWARE
// (pure data — no CSS, no DOM). An element imports `getEngine()` from ./engine.js,
// registers its source once, and runs queries; the element owns render + theme.
//
// The engine is SQLite, resolved by the Host per context: the workbook's native
// SQLite VFS over the runtime (Dock `vfs-query`), in-page sqlite-wasm when static,
// or the in-JS subset floor. One SQL dialect everywhere — write SQLite SQL.
//
// ─────────────────────────────────────────────────────────────────────────────
// Result shape — every query (runtime VFS, in-page sqlite-wasm, or the in-JS
// floor) returns EXACTLY this. Every surface must code against this and nothing
// else:
//
//   /** @typedef {Object} WbQueryResult
//    *  @property {string[]}    columns  ordered column names
//    *  @property {any[][]}     rows     row-major; rows[i][j] is column j of row i
//    *  @property {WbColType[]} types    per-column logical type (columns.length)
//    *  @property {number}      rowCount rows.length (convenience)
//    *  @property {string}      [engine] which tier answered: runtime|sqlite-wasm|memory
//    *  @property {string}      [sql]    the SQL actually executed (debug)
//    */
//
//   WbColType ∈ "number" | "integer" | "string" | "boolean" | "date" | "json"
//
// Engine surface (engine.js implements this; every surface reuses it verbatim):
//
//   query(sql: string, params?: any[]) -> Promise<WbQueryResult>
//   register(name: string, source: WbSource) -> Promise<void>   // makes a table
//   whenRegistered(name: string) -> Promise<void>  // await before querying it
//   available() -> boolean      // is a real SQLite tier reachable (vs the floor)
//   writable() -> boolean       // are writes durable (runtime VFS) vs local/none
//   provider() -> string        // "runtime" | "sqlite-wasm" | "memory"
//
// Source registration — "a workbook's data IS its source" (for INLINE data; a
// real workbook's tables already live in its SQLite VFS, no registration). One of:
//
//   { rows: object[] }                         inline array of row objects
//   { columns: string[], rows: any[][] }       columnar inline
//   { csv: string }                            CSV text (header row)
//   { json: string | object[] }                JSON text or parsed array
//   { url: string, format?: "csv"|"json" }     fetched (browser/runtime)
//
// `params` use positional `?` placeholders (SQLite style). All tiers bind the same.
// ─────────────────────────────────────────────────────────────────────────────

/** Normalize any WbSource into { columns, rows(object[]) } for registration. */
export function normalizeSource(src) {
  if (!src || typeof src !== "object") throw new Error("wb-data: source must be an object");
  if (Array.isArray(src.rows) && src.columns) {
    // columnar inline → objects
    const cols = src.columns;
    return { columns: cols, rows: src.rows.map((r) => objFromRow(cols, r)) };
  }
  if (Array.isArray(src.rows)) {
    const cols = inferColumns(src.rows);
    return { columns: cols, rows: src.rows };
  }
  if (typeof src.csv === "string") return parseCsv(src.csv);
  if (src.json != null) {
    const arr = typeof src.json === "string" ? JSON.parse(src.json) : src.json;
    if (!Array.isArray(arr)) throw new Error("wb-data: json source must be an array of rows");
    return { columns: inferColumns(arr), rows: arr };
  }
  throw new Error("wb-data: unsupported source (need rows|columns+rows|csv|json|url|arrow)");
}

function objFromRow(cols, row) {
  if (Array.isArray(row)) {
    const o = {};
    cols.forEach((c, i) => (o[c] = row[i]));
    return o;
  }
  return row;
}

function inferColumns(rows) {
  const seen = new Set();
  const cols = [];
  for (const r of rows) for (const k of Object.keys(r)) if (!seen.has(k)) { seen.add(k); cols.push(k); }
  return cols;
}

/** Minimal RFC-4180-ish CSV parse (quotes, escaped quotes, commas, newlines). */
export function parseCsv(text) {
  const rows = [];
  let field = "", row = [], inQ = false;
  const t = text.replace(/\r\n?/g, "\n");
  for (let i = 0; i < t.length; i++) {
    const c = t[i];
    if (inQ) {
      if (c === '"') { if (t[i + 1] === '"') { field += '"'; i++; } else inQ = false; }
      else field += c;
    } else if (c === '"') inQ = true;
    else if (c === ",") { row.push(field); field = ""; }
    else if (c === "\n") { row.push(field); rows.push(row); field = ""; row = []; }
    else field += c;
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  const filtered = rows.filter((r) => r.length > 1 || (r.length === 1 && r[0] !== ""));
  if (!filtered.length) return { columns: [], rows: [] };
  const columns = filtered[0].map((h) => h.trim());
  const out = filtered.slice(1).map((r) => {
    const o = {};
    columns.forEach((col, i) => (o[col] = coerce(r[i])));
    return o;
  });
  return { columns, rows: out };
}

/** Coerce a CSV/string cell to number/boolean where it is unambiguous. */
export function coerce(v) {
  if (v == null) return null;
  const s = String(v).trim();
  if (s === "") return null;
  if (s === "true") return true;
  if (s === "false") return false;
  if (/^-?\d+$/.test(s)) return parseInt(s, 10);
  if (/^-?\d*\.\d+$/.test(s)) return parseFloat(s);
  return s;
}

/** Infer a WbColType from a sample of column values. */
export function inferType(values) {
  let n = 0, allInt = true, num = 0, bool = 0, total = 0;
  for (const v of values) {
    if (v == null) continue;
    total++;
    if (typeof v === "boolean") { bool++; continue; }
    if (typeof v === "number") { num++; if (!Number.isInteger(v)) allInt = false; continue; }
    n++;
  }
  if (total === 0) return "string";
  if (bool === total) return "boolean";
  if (num === total) return allInt ? "integer" : "number";
  return "string";
}

/** Build a WbQueryResult (columns/rows array-of-array/types) from row objects. */
export function resultFromObjects(rowObjs, columns, engine, sql) {
  const cols = columns || inferColumns(rowObjs);
  const rows = rowObjs.map((o) => cols.map((c) => o[c] ?? null));
  const types = cols.map((c, j) => inferType(rows.map((r) => r[j])));
  return { columns: cols, rows, types, rowCount: rows.length, engine, sql };
}

// workponents · data — the shared SQLite seam, behind the Host/Dock membrane.
//
// ONE engine, every data surface: `tables`, `data-viz`, `maps`, `records`, and
// `search` all import `getEngine()` and consume the contract in ./contract.js.
// A component NEVER picks where SQL runs — the Host resolves the tier by context
// (the platform-model `local | runtime` seam):
//
//   • runtime — a Workbooks runtime/nexus is connected. SQL routes over the Dock
//     to the workbook's native SQLite VFS (`exqlite`, server-side) via the
//     tenant query route. Data stays OUT of the client; writes are durable
//     (Litestream). This is "the unbundling" — the SQLite is docked out to the
//     nexus so it can be edited live.
//
//   • sqlite-wasm — no runtime. Real SQLite in the page (./sqlite-wasm.js): the
//     full dialect, byte-compatible with the runtime's `exqlite`. ~1MB, lazily
//     loaded once. "The SQLite layer in the workbook itself" — and, ahead, the
//     engine that opens a static workbook's hydrated embedded VFS (the single-HTML
//     format: VFS embedded as a compressed blob, hydrated via DecompressionStream).
//
//   • memory — last-resort floor (./memory-sql.js): the zero-dep in-JS SQL subset,
//     used only if sqlite-wasm can't load (offline, no CDN/self-host). It is a
//     SUBSET — not real SQLite — so sqlite-wasm is preferred whenever reachable.
//
// One SQLite dialect everywhere — native `exqlite` (runtime) and sqlite-wasm
// (browser) are two builds of the same engine, and a workbook's `.sqlite` is
// byte-portable between them. (DuckDB-wasm was removed: 34MB, a divergent dialect,
// and redundant — the workbook already ships SQLite.)

import { getHost } from "../core/host.js";
import { normalizeSource, resultFromObjects } from "./contract.js";
import { WasmSqlite, bootSqlite } from "./sqlite-wasm.js";
import { MemorySql } from "./memory-sql.js";

let _engine = null;

/** The shared engine singleton. Lazy, idempotent — call from any element. */
export function getEngine() {
  if (!_engine) _engine = new WbDataEngine();
  return _engine;
}

export class WbDataEngine {
  constructor() {
    this._host = getHost();
    this._sqlite = new WasmSqlite();  // real in-page SQLite (the local tier)
    this._memory = new MemorySql();   // zero-dep subset (load-failure floor only)
    this._sources = new Map();        // name -> normalized {columns, rows}
    this._provider = null;            // resolved on first use
    this._initPromise = null;
    this._regWaiters = new Map();     // name -> [resolve, ...] awaiting registration
    this._inflightRegs = new Set();   // register() promises still settling
    // Runtime SQL-over-VFS route (tenant SQLite via the Dock). `{tenant}` is
    // filled from the Host. Override per deploy if a runtime exposes another path.
    this.vfsQueryPath = "/api/library/{tenant}/query";
  }

  /**
   * Resolve once `name` is registered (and live on the active provider). Returns
   * immediately if it already is. Lets a declarative element with `src-name`
   * upgrade BEFORE the page calls register() without racing an unknown table —
   * the one ordering hazard shared by every surface.
   */
  whenRegistered(name) {
    if (this._sources.has(name)) return Promise.resolve();
    return new Promise((resolve) => {
      const arr = this._regWaiters.get(name) || [];
      arr.push(resolve);
      this._regWaiters.set(name, arr);
    });
  }

  /** Which tier answers: "runtime" (native VFS) | "sqlite-wasm" (local) | "memory". */
  provider() { return this._provider || (this._runtimeReady() ? "runtime" : "sqlite-wasm"); }

  /** Is a real SQLite engine reachable (runtime VFS or in-page sqlite-wasm)? */
  available() { return this._runtimeReady() || this._provider === "sqlite-wasm"; }

  /** Are writes durable (runtime/nexus `exqlite`) vs local/ephemeral or none? */
  writable() { return this._runtimeReady(); }

  _runtimeReady() {
    return this._host.available("vfs") || (this._host.runtimeUrl != null);
  }

  /** Register a named source so SQL can `FROM <name>`. Idempotent per name. */
  register(name, source) {
    // Track the in-flight promise so a query that references this table before
    // it lands (an element querying a table a SIBLING registers — no src-name
    // declared) can await it and retry, instead of failing "no such table".
    const p = this._doRegister(name, source);
    this._inflightRegs.add(p);
    p.finally(() => this._inflightRegs.delete(p));
    return p;
  }

  async _doRegister(name, source) {
    const norm = normalizeSource(source);
    this._sources.set(name, norm);
    // Seed the floor too, so a sqlite-wasm load failure still answers.
    this._memory.register(name, norm);
    await this._ensureProvider();
    if (this._provider === "runtime") {
      // Inline data pushed into a docked workbook (best-effort). Real workbook
      // tables already live in the VFS and need no registration.
      try {
        await this._host.request(this._regPath(), { body: { name, columns: norm.columns, rows: norm.rows } });
      } catch { /* runtime ingest best-effort; the floor still answers */ }
    } else if (this._provider === "sqlite-wasm") {
      await this._sqlite.register(name, norm);
    }
    // Now queryable on the active provider — release anyone awaiting this source.
    const waiters = this._regWaiters.get(name);
    if (waiters) { this._regWaiters.delete(name); for (const r of waiters) r(); }
  }

  /** query(sql, params?) -> Promise<WbQueryResult>. Every surface's one call. */
  async query(sql, params = []) {
    await this._ensureProvider();
    if (this._provider === "runtime") {
      try {
        const res = await this._host.request(this._queryPath(), { body: { sql, params } });
        const shaped = shapeRuntime(res, sql);
        if (shaped) return shaped;
      } catch { /* fall through to the local engine */ }
    }
    if (this._provider === "sqlite-wasm") {
      try {
        return await this._sqlite.query(sql, params);
      } catch (e) {
        // The table may simply not be registered YET (a sibling's register() is
        // mid-flight). Wait for pending registrations, then retry once.
        if (/no such table/i.test(String(e && e.message || e)) && this._inflightRegs.size) {
          await Promise.allSettled([...this._inflightRegs]);
          return this._sqlite.query(sql, params);
        }
        throw e;
      }
    }
    // Last-resort floor — the zero-dep in-JS subset (sqlite-wasm unavailable).
    return this._memory.query(sql, params);
  }

  // ── provider resolution ────────────────────────────────────────────────────
  async _ensureProvider() {
    if (this._provider) return;
    if (this._initPromise) return this._initPromise;
    // Runtime/nexus SQLite VFS when connected; else real in-page sqlite-wasm;
    // the in-JS subset only if sqlite-wasm can't load (offline, no CDN/self-host).
    this._initPromise = (async () => {
      if (this._runtimeReady()) { this._provider = "runtime"; return; }
      try {
        await bootSqlite();
        this._provider = "sqlite-wasm";
        // No re-registration here: every source arrives via register(), which
        // registers into the resolved provider after awaiting this boot. Looping
        // here too would double-register the same table concurrently (DROP/CREATE
        // racing a sibling's DDL) → transient "no such table".
      } catch {
        this._provider = "memory";
      }
    })();
    return this._initPromise;
  }

  _queryPath() {
    return this.vfsQueryPath.replace("{tenant}", encodeURIComponent(this._host.tenant || "local"));
  }
  _regPath() {
    return this._queryPath().replace(/\/query$/, "/register");
  }
}

/**
 * Shape a runtime SQL response into a WbQueryResult. Tolerant of the row shapes a
 * runtime may return ({columns, rows[][]} columnar, or an array of row-objects).
 * Returns null when unrecognized so query() falls back to the local floor.
 */
function shapeRuntime(res, sql) {
  if (!res) return null;
  if (Array.isArray(res)) {
    return resultFromObjects(res, res.length ? Object.keys(res[0]) : [], "runtime", sql);
  }
  if (Array.isArray(res.rows) && Array.isArray(res.columns)) {
    const types = res.types || res.columns.map(() => "string");
    return { columns: res.columns, rows: res.rows, types, rowCount: res.rows.length, engine: "runtime", sql };
  }
  if (Array.isArray(res.rows)) {
    const cols = res.columns || (res.rows.length ? Object.keys(res.rows[0]) : []);
    return resultFromObjects(res.rows, cols, "runtime", sql);
  }
  return null;
}

// workponents · data — the shared in-WASM data layer for the DuckDB trio.
//
// ONE engine, three surfaces. `tables`, `data-viz`, and `maps` all import from
// here and code against the contract in ./contract.js. Framework-agnostic,
// zero-dependency, token-unaware (pure data — no DOM, no CSS).
//
//   import { getEngine } from "../../data/index.js";
//   const db = getEngine();
//   await db.register("orders", { csv: "...." });        // a workbook's data IS its source
//   const res = await db.query("SELECT region, sum(rev) AS rev FROM orders GROUP BY region");
//   // res = { columns, rows (array-of-array), types, rowCount, engine }
//
// data-viz / maps consume the SAME shape: a chart reads res.rows[i][j] by
// res.columns; a geo-query reads lat/lon columns off the same result. Register
// once, query from every surface on the page (shared connection).
export { getEngine, WbDataEngine } from "./engine.js";
export {
  normalizeSource, parseCsv, coerce, inferType, resultFromObjects,
} from "./contract.js";
export { MemorySql } from "./memory-sql.js";

// workponents · data — the in-JS fallback engine (zero-dep, offline).
//
// A small SQL-subset interpreter so the surfaces compute REAL sort/filter/aggregate
// IN an engine even with no runtime tier AND no network (CDN blocked). It is the
// LAST RESORT behind ./engine.js — when the runtime VFS (Host) or in-page
// sqlite-wasm is reachable, real SQLite answers instead and this is never touched.
// It is a SUBSET (no CAST, joins, window fns) — not real SQLite; prefer the tiers.
//
// Supported (one flat table per query, the basic grid/chart/geo-query needs):
//   SELECT <proj> FROM <table>
//     [WHERE <cond> [AND/OR <cond>]...]
//     [GROUP BY <col>[, <col>]...]
//     [ORDER BY <col|alias> [ASC|DESC]][, ...]
//     [LIMIT n [OFFSET m]]
//   proj: *, col, col AS alias, AGG(col) [AS alias], COUNT(*)
//   agg:  COUNT | SUM | AVG | MIN | MAX
//   cond: col OP value   OP ∈ = != <> < <= > >= LIKE   value: number|'str'|?
//   ? params bind positionally (SQLite style).
//
// Deliberately small. For anything beyond this, a real engine is required — the
// element degrades by surfacing the engine name so authors know which tier ran.

import { resultFromObjects } from "./contract.js";

const AGG_RE = /^(count|sum|avg|min|max)\s*\(\s*(\*|[\w."]+)\s*\)$/i;

export class MemorySql {
  constructor() {
    /** @type {Map<string,{columns:string[],rows:object[]}>} */
    this.tables = new Map();
  }

  register(name, normalized) {
    this.tables.set(name, normalized);
  }

  /** query(sql, params?) -> WbQueryResult */
  query(sql, params = []) {
    const q = parse(sql);
    const tbl = this.tables.get(q.from);
    if (!tbl) throw new Error(`wb-data(memory): unknown table "${q.from}"`);
    let rows = tbl.rows.slice();
    const binds = params.slice();

    // WHERE
    if (q.where.length) {
      rows = rows.filter((r) => evalWhere(r, q.where, binds.slice()));
    }

    let out;
    const hasAgg = q.select.some((s) => s.agg);
    if (q.groupBy.length || hasAgg) {
      out = aggregate(rows, q);
    } else {
      out = rows.map((r) => projectRow(r, q.select, tbl.columns));
    }

    // ORDER BY (by output alias/name)
    for (let i = q.orderBy.length - 1; i >= 0; i--) {
      const { key, dir } = q.orderBy[i];
      out.sort((a, b) => cmp(a[key], b[key]) * (dir === "desc" ? -1 : 1));
    }

    // LIMIT / OFFSET
    if (q.offset) out = out.slice(q.offset);
    if (q.limit != null) out = out.slice(0, q.limit);

    const columns = q.star ? (out[0] ? Object.keys(out[0]) : tbl.columns) : q.select.map((s) => s.alias);
    return resultFromObjects(out, columns, "memory", sql);
  }
}

function projectRow(r, select, allCols) {
  const o = {};
  for (const s of select) {
    if (s.star) { for (const c of allCols) o[c] = r[c]; continue; }
    o[s.alias] = r[s.col];
  }
  return o;
}

function aggregate(rows, q) {
  const groupCols = q.groupBy;
  const groups = new Map();
  for (const r of rows) {
    const key = groupCols.map((c) => r[c]).join("");
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(r);
  }
  if (!groups.size && !groupCols.length) groups.set("", []); // global agg over empty set
  const out = [];
  for (const bucket of groups.values()) {
    const o = {};
    for (const s of q.select) {
      if (s.star && !s.agg) { for (const c of groupCols) o[c] = bucket[0]?.[c]; continue; }
      if (s.agg) o[s.alias] = applyAgg(s.agg, s.col, bucket);
      else o[s.alias] = bucket[0]?.[s.col] ?? null; // grouping column
    }
    out.push(o);
  }
  return out;
}

function applyAgg(agg, col, bucket) {
  if (agg === "count") return col === "*" ? bucket.length : bucket.filter((r) => r[col] != null).length;
  const nums = bucket.map((r) => Number(r[col])).filter((n) => !Number.isNaN(n));
  if (!nums.length) return null;
  if (agg === "sum") return nums.reduce((a, b) => a + b, 0);
  if (agg === "avg") return nums.reduce((a, b) => a + b, 0) / nums.length;
  if (agg === "min") return Math.min(...nums);
  if (agg === "max") return Math.max(...nums);
  return null;
}

function cmp(a, b) {
  if (a == null && b == null) return 0;
  if (a == null) return -1;
  if (b == null) return 1;
  if (typeof a === "number" && typeof b === "number") return a - b;
  return String(a).localeCompare(String(b), undefined, { numeric: true });
}

function evalWhere(row, clauses, binds) {
  // clauses: [cond, {bool}, cond, ...] — left-to-right, AND/OR (no precedence/parens)
  let acc = null, op = "and";
  for (const node of clauses) {
    if (node.bool) { op = node.bool; continue; }
    const v = testCond(row, node, binds);
    acc = acc == null ? v : op === "and" ? acc && v : acc || v;
  }
  return acc == null ? true : acc;
}

function testCond(row, c, binds) {
  const lhs = row[c.col];
  const rhs = c.param ? binds.shift() : c.value;
  switch (c.op) {
    case "=": return looseEq(lhs, rhs);
    case "!=": case "<>": return !looseEq(lhs, rhs);
    case "<": return num(lhs) < num(rhs);
    case "<=": return num(lhs) <= num(rhs);
    case ">": return num(lhs) > num(rhs);
    case ">=": return num(lhs) >= num(rhs);
    case "like": return likeMatch(String(lhs ?? ""), String(rhs ?? ""));
    default: return false;
  }
}

function looseEq(a, b) {
  if (typeof a === "number" || typeof b === "number") return num(a) === num(b);
  return String(a) === String(b);
}
function num(v) { const n = Number(v); return Number.isNaN(n) ? v : n; }
function likeMatch(s, pat) {
  const re = new RegExp("^" + pat.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/%/g, ".*").replace(/_/g, ".") + "$", "i");
  return re.test(s);
}

// ── parser ───────────────────────────────────────────────────────────────────
function parse(sql) {
  const s = sql.trim().replace(/;$/, "");
  const m = /^select\s+(.+?)\s+from\s+([\w."]+)(.*)$/is.exec(s);
  if (!m) throw new Error("wb-data(memory): only SELECT … FROM … is supported");
  const projRaw = m[1], from = unquote(m[2]);
  let rest = m[3] || "";

  const where = [], groupBy = [], orderBy = [];
  let limit = null, offset = 0;

  const limitM = /\blimit\s+(\d+)(?:\s+offset\s+(\d+))?/i.exec(rest);
  if (limitM) { limit = +limitM[1]; offset = limitM[2] ? +limitM[2] : 0; rest = rest.replace(limitM[0], ""); }
  const offM = /\boffset\s+(\d+)/i.exec(rest);
  if (offM) { offset = +offM[1]; rest = rest.replace(offM[0], ""); }

  const orderM = /\border\s+by\s+(.+?)(?=\bgroup\s+by\b|$)/is.exec(rest);
  if (orderM) {
    rest = rest.replace(orderM[0], "");
    for (const part of orderM[1].split(",")) {
      const [, key, dir] = /^\s*([\w."]+)\s*(asc|desc)?\s*$/i.exec(part) || [];
      if (key) orderBy.push({ key: unquote(key), dir: (dir || "asc").toLowerCase() });
    }
  }
  const groupM = /\bgroup\s+by\s+(.+?)(?=\border\s+by\b|$)/is.exec(rest);
  if (groupM) {
    rest = rest.replace(groupM[0], "");
    for (const p of groupM[1].split(",")) groupBy.push(unquote(p.trim()));
  }
  const whereM = /\bwhere\s+(.+)$/is.exec(rest);
  if (whereM) parseWhere(whereM[1].trim(), where);

  const select = [];
  let star = false;
  for (const raw of splitTop(projRaw)) {
    const item = raw.trim();
    if (item === "*") { select.push({ star: true }); star = true; continue; }
    const asM = /\s+as\s+([\w]+)\s*$/i.exec(item);
    const alias = asM ? asM[1] : null;
    const expr = asM ? item.slice(0, asM.index).trim() : item;
    const aggM = AGG_RE.exec(expr);
    if (aggM) {
      const agg = aggM[1].toLowerCase();
      const col = aggM[2] === "*" ? "*" : unquote(aggM[2]);
      select.push({ agg, col, alias: alias || `${agg}_${col === "*" ? "all" : col}` });
    } else {
      const col = unquote(expr);
      select.push({ col, alias: alias || col });
    }
  }
  return { select, star, from, where, groupBy, orderBy, limit, offset };
}

function parseWhere(str, out) {
  // split on top-level AND/OR (no parens support — flat list)
  const parts = str.split(/\s+(and|or)\s+/i);
  for (let i = 0; i < parts.length; i++) {
    if (i % 2 === 1) { out.push({ bool: parts[i].toLowerCase() }); continue; }
    // accept the floor's `CAST(col AS TYPE)` coercion (used by search-box/-command
    // so non-string columns LIKE-match) — the memory tier is the floor's own offline
    // engine, so it must run the floor's own query. Reduce the cast to the column;
    // the JS comparison is type-agnostic (String() coerces), so the cast is a no-op.
    const cast = /^\s*CAST\s*\(\s*([\w."]+)\s+AS\s+\w+\s*\)\s*(<=|>=|<>|!=|=|<|>|like)\s*(.+?)\s*$/i.exec(parts[i]);
    const m = cast || /^\s*([\w."]+)\s*(<=|>=|<>|!=|=|<|>|like)\s*(.+?)\s*$/i.exec(parts[i]);
    if (!m) throw new Error(`wb-data(memory): bad WHERE clause "${parts[i]}"`);
    const col = unquote(m[1]), op = m[2].toLowerCase();
    let value = m[3].trim(), param = false;
    if (value === "?") param = true;
    else if (/^'.*'$/.test(value)) value = value.slice(1, -1).replace(/''/g, "'");
    else if (/^-?\d*\.?\d+$/.test(value)) value = parseFloat(value);
    out.push({ col, op, value, param });
  }
}

function splitTop(s) {
  // split on commas not inside parentheses
  const out = []; let depth = 0, cur = "";
  for (const c of s) {
    if (c === "(") depth++;
    else if (c === ")") depth--;
    if (c === "," && depth === 0) { out.push(cur); cur = ""; } else cur += c;
  }
  if (cur.trim()) out.push(cur);
  return out;
}

function unquote(s) { return String(s).trim().replace(/^"(.*)"$/, "$1"); }

// workponents · data — the browser-local SQLite tier (sqlite-wasm).
//
// Real SQLite, in the page: the full dialect, byte-compatible with the runtime's
// native `exqlite` VFS. This is "the SQLite layer in the workbook itself" for the
// static / no-runtime case — and, ahead, the engine that opens a workbook's
// hydrated embedded VFS (the single-HTML format). ~1MB, lazily loaded once.
//
// Override the asset base via `window.__WB_SQLITE_WASM__` (a base URL ending in
// `/`) to self-host instead of the CDN — e.g. ship the wasm with the workbook.
import { inferType } from "./contract.js";

const DEFAULT_BASE = "https://cdn.jsdelivr.net/npm/@sqlite.org/sqlite-wasm@3.50.1-build1/";
let _boot = null;

/** Boot sqlite-wasm once (idempotent). Resolves { sqlite3, db } (in-memory db). */
export function bootSqlite() {
  if (_boot) return _boot;
  _boot = (async () => {
    if (typeof window === "undefined") throw new Error("sqlite-wasm needs a browser");
    const base = window.__WB_SQLITE_WASM__ || DEFAULT_BASE;
    const mod = await import(/* @vite-ignore */ base + "index.mjs");
    const sqlite3 = await mod.default({ locateFile: (f) => base + "sqlite-wasm/jswasm/" + f });
    return { sqlite3, db: new sqlite3.oo1.DB(":memory:", "c") };
  })();
  return _boot;
}

/** A WbDataEngine tier backed by real in-page SQLite. Same contract as the floor. */
export class WasmSqlite {
  /** Register a normalized source ({columns, rows: object[]}) as a table. */
  async register(name, norm) {
    const { db } = await bootSqlite();
    const cols = norm.columns;
    db.exec(`DROP TABLE IF EXISTS ${ident(name)}`);
    db.exec(`CREATE TABLE ${ident(name)} (${cols.map(ident).join(", ")})`);
    if (!norm.rows.length) return;
    const stmt = db.prepare(`INSERT INTO ${ident(name)} VALUES (${cols.map(() => "?").join(", ")})`);
    try {
      db.exec("BEGIN");
      for (const row of norm.rows) {
        stmt.bind(cols.map((c) => sqlVal(row[c]))).step();
        stmt.reset(true);
      }
      db.exec("COMMIT");
    } finally {
      stmt.finalize();
    }
  }

  /** Run SQL → WbQueryResult (row-major arrays + per-column inferred types). */
  async query(sql, params = []) {
    const { db } = await bootSqlite();
    const columns = [];
    const rows = db.exec({
      sql,
      bind: params && params.length ? params : undefined,
      rowMode: "array",
      columnNames: columns,
      returnValue: "resultRows",
    });
    const types = columns.map((_c, j) => inferType(rows.map((r) => r[j])));
    return { columns, rows, types, rowCount: rows.length, engine: "sqlite-wasm", sql };
  }
}

function ident(name) { return '"' + String(name).replace(/"/g, '""') + '"'; }

/** Coerce a JS value to something sqlite-wasm can bind (no booleans/objects). */
function sqlVal(v) {
  if (v == null) return null;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (typeof v === "number" || typeof v === "string" || typeof v === "bigint") return v;
  return JSON.stringify(v);
}

// files · shared type helpers — pure, zero-dep, DOM-free. Both <wb-drive> and
// <wb-file> classify a file by its mime/type or extension into a small kind set
// (image | video | audio | text | pdf | archive | code | font | file), pick a
// typed glyph, and format size/timestamps. One home, no copy-paste.

const EXT_KIND = {
  // images
  png: "image", jpg: "image", jpeg: "image", gif: "image", webp: "image",
  svg: "image", avif: "image", bmp: "image", ico: "image", heic: "image",
  // video
  mp4: "video", webm: "video", mov: "video", mkv: "video", avi: "video", m4v: "video",
  // audio
  mp3: "audio", wav: "audio", ogg: "audio", flac: "audio", m4a: "audio", aac: "audio",
  // text / docs
  txt: "text", md: "text", org: "text", rst: "text", log: "text", csv: "text",
  // pdf
  pdf: "pdf",
  // code
  js: "code", mjs: "code", ts: "code", jsx: "code", tsx: "code", json: "code",
  html: "code", css: "code", py: "code", rs: "code", go: "code", c: "code",
  cpp: "code", h: "code", ex: "code", exs: "code", sh: "code", sql: "code",
  yaml: "code", yml: "code", toml: "code", xml: "code",
  // archives
  zip: "archive", tar: "archive", gz: "archive", tgz: "archive", rar: "archive",
  "7z": "archive", bz2: "archive",
  // fonts
  woff: "font", woff2: "font", ttf: "font", otf: "font",
};

const GLYPH = {
  image: "🖼", video: "🎞", audio: "♪", text: "📄", pdf: "📕",
  code: "{ }", archive: "🗜", font: "Aa", file: "📦",
};

/** Lowercase extension (no dot) from a name or "image/png" → "png". */
export function extOf(s) {
  if (!s) return "";
  s = String(s);
  if (s.includes("/")) return s.split("/").pop().split("+")[0].toLowerCase(); // a mime subtype
  const dot = s.lastIndexOf(".");
  return dot >= 0 ? s.slice(dot + 1).toLowerCase() : "";
}

/** Classify into a kind from a mime/type string and/or a filename. */
export function fileKind(type, name) {
  const t = String(type || "").toLowerCase();
  if (t.startsWith("image/")) return "image";
  if (t.startsWith("video/")) return "video";
  if (t.startsWith("audio/")) return "audio";
  if (t === "application/pdf") return "pdf";
  if (t.startsWith("text/")) return "text";
  if (/(zip|x-tar|gzip|x-7z|x-rar)/.test(t)) return "archive";
  if (t.startsWith("font/")) return "font";
  if (/(javascript|json|html|xml|x-sh|x-python)/.test(t)) return "code";
  // fall back to the extension of name (or a bare ext in `type`)
  const ext = extOf(name) || (t && !t.includes("/") ? t : "");
  return EXT_KIND[ext] || "file";
}

/** A typed glyph for a kind (text-only; renders in any theme). */
export function kindGlyph(kind) { return GLYPH[kind] || GLYPH.file; }

/** Human byte size: 1536 → "1.5 KB". Accepts number or numeric string. */
export function fmtBytes(n) {
  n = Number(n);
  if (!isFinite(n) || n < 0) return "—";
  if (n < 1024) return `${n} B`;
  const u = ["KB", "MB", "GB", "TB"];
  let i = -1;
  do { n /= 1024; i++; } while (n >= 1024 && i < u.length - 1);
  return `${n < 10 ? n.toFixed(1) : Math.round(n)} ${u[i]}`;
}

/** Friendly timestamp: ISO/epoch → "Nov 3, 2024". Best-effort, never throws. */
export function fmtWhen(v) {
  if (v == null || v === "") return "—";
  let d;
  if (typeof v === "number") d = new Date(v < 1e12 ? v * 1000 : v); // s vs ms epoch
  else d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
}

/** Short content-hash for display: "sha256:abcd…1234" → "abcd…1234". */
export function shortHash(h) {
  if (!h) return "";
  h = String(h).replace(/^[a-z0-9]+:/i, "");
  return h.length > 14 ? `${h.slice(0, 8)}…${h.slice(-4)}` : h;
}
